package kindergarten

import (
	"errors"
	"fmt"
	"sort"
	"strings"
)

// Garden holds the plants assigned to each child in the class.
type Garden struct {
	plants map[string][]string
}

// plantNames maps the diagram cup codes to plant names.
var plantNames = map[byte]string{
	'G': "grass",
	'C': "clover",
	'R': "radishes",
	'V': "violets",
}

// NewGarden builds a Garden from a two-row diagram and a list of children.
//
// The diagram argument starts each row with a '\n'.  This allows Go's
// raw string literals to present diagrams in source code nicely as two
// rows flush left, for example,
//
//     diagram := `
//     VVCCGG
//     VVCCGG`
//
// Cups are assigned to the children alphabetically by name, two cups per
// row. The children argument is not modified.
func NewGarden(diagram string, children []string) (*Garden, error) {
	if len(diagram) < 2 || diagram[0] != '\n' {
		return nil, errors.New("diagram must start with a newline")
	}
	rows := strings.Split(diagram, "\n")
	if len(rows) != 3 {
		return nil, errors.New("diagram must contain exactly two rows")
	}
	row1, row2 := rows[1], rows[2]
	if len(row1) != len(row2) {
		return nil, errors.New("diagram rows must be the same length")
	}
	if len(row1)%2 != 0 {
		return nil, errors.New("diagram must contain an even number of cups")
	}
	for _, c := range row1 + row2 {
		if _, ok := plantNames[c]; !ok {
			return nil, fmt.Errorf("invalid cup code %q", c)
		}
	}
	seen := make(map[string]bool, len(children))
	for _, child := range children {
		if seen[child] {
			return nil, fmt.Errorf("duplicate child %q", child)
		}
		seen[child] = true
	}

	// Sort a copy so the caller's slice is left untouched.
	names := make([]string, len(children))
	copy(names, children)
	sort.Strings(names)

	// Flatten the two rows into one sequence of plant names: each child
	// gets the next two cups from each row, in order.
	cups := make([]string, 0, len(row1)+len(row2))
	for _, c := range row1 + row2 {
		cups = append(cups, plantNames[c])
	}

	plants := make(map[string][]string, len(names))
	for i, child := range names {
		// Only assign cups that actually exist for this child.
		if 2*i+2 <= len(cups) {
			childCups := make([]string, 2)
			copy(childCups, cups[2*i:2*i+2])
			plants[child] = childCups
		}
	}
	return &Garden{plants: plants}, nil
}

// Plants returns the four plants assigned to the named child, or
// ok = false if the child is not in the garden.
func (g *Garden) Plants(child string) ([]string, bool) {
	plants, ok := g.plants[child]
	return plants, ok
}

